namespace sv_09c3e4ef52e74db2bb2c98d23556b022.Services;

/// <summary>
/// Scoped state that holds the current low-stock alert count and notifies all subscribers
/// when new data arrives. Polling is controlled externally (started/stopped by a page component).
/// </summary>
public class InventoryAlertState : IDisposable
{
    private readonly InventoryAlertService _alertService;
    private readonly WarehouseState _warehouseState;
    private CancellationTokenSource? _pollCts;
    private int _subscriberCount;

    public int LowStockCount { get; private set; }

    public event Action? OnChange;

    public InventoryAlertState(InventoryAlertService alertService, WarehouseState warehouseState)
    {
        _alertService = alertService;
        _warehouseState = warehouseState;
        _warehouseState.OnChange += OnWarehouseChanged;
    }

    /// <summary>
    /// Start polling. Multiple callers are ref-counted; polling runs while at least one subscriber exists.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _pollCts = new CancellationTokenSource();
            _ = PollLoopAsync(_pollCts.Token);
        }
    }

    /// <summary>
    /// Stop polling. Only actually stops when all subscribers have unsubscribed.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _pollCts?.Cancel();
            _pollCts?.Dispose();
            _pollCts = null;
        }
    }

    public async Task RefreshAsync()
    {
        LowStockCount = await _alertService.GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
        OnChange?.Invoke();
    }

    private async void OnWarehouseChanged()
    {
        // When the warehouse changes, immediately refresh alert data
        await RefreshAsync();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        // Do an immediate first fetch
        await RefreshAsync();

        try
        {
            while (await timer.WaitForNextTickAsync(ct))
            {
                await RefreshAsync();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected when polling is stopped
        }
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= OnWarehouseChanged;
        _pollCts?.Cancel();
        _pollCts?.Dispose();
    }
}

