@inject Services.WarehouseState WarehouseState
@implements IDisposable
@rendermode InteractiveServer

<div class="warehouse-selector">
    <label class="form-label mb-1 text-light small">Current Warehouse</label>
    <select class="form-select form-select-sm"
            value="@WarehouseState.SelectedWarehouseId"
            @onchange="OnWarehouseSelected">
        @foreach (var wh in WarehouseState.Warehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnStateChanged;
    }

    private void OnWarehouseSelected(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
        {
            WarehouseState.SetWarehouse(id);
        }
    }

    private void OnStateChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        WarehouseState.OnChange -= OnStateChanged;
    }
}

@inject Services.InventoryAlertState AlertState
@implements IDisposable
@rendermode InteractiveServer

<span class="alert-badge position-relative">
    <span class="bi bi-exclamation-triangle-fill-nav-menu" aria-hidden="true"></span>
    @if (AlertState.LowStockCount > 0)
    {
        <span class="badge bg-danger rounded-pill">@AlertState.LowStockCount</span>
    }
    else
    {
        <span class="badge bg-success rounded-pill">0</span>
    }
</span>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertState.OnChange += _handler;
    }

    public void Dispose()
    {
        if (_handler is not null)
        {
            AlertState.OnChange -= _handler;
        }
    }
}

@page "/dashboard"
@inject Services.WarehouseState WarehouseState
@inject Services.InventoryAlertState AlertState
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Dashboard — @WarehouseState.SelectedWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-header">
                <h5 class="mb-0">Current Warehouse</h5>
            </div>
            <div class="card-body">
                <p class="fs-4 mb-0">@WarehouseState.SelectedWarehouseName</p>
                <small class="text-muted">ID: @WarehouseState.SelectedWarehouseId</small>
            </div>
        </div>
    </div>

    <div class="col-md-6">
        <div class="card @(AlertState.LowStockCount > 5 ? "border-danger" : "border-success")">
            <div class="card-header">
                <h5 class="mb-0">Low Stock Alerts</h5>
            </div>
            <div class="card-body text-center">
                <p class="display-4 mb-0 @(AlertState.LowStockCount > 5 ? "text-danger" : "text-success")">
                    @AlertState.LowStockCount
                </p>
                <small class="text-muted">items below minimum level</small>
                <div class="mt-2">
                    <button class="btn btn-sm btn-outline-secondary" @onclick="RefreshNow">
                        Refresh Now
                    </button>
                </div>
            </div>
        </div>
    </div>
</div>

<div class="row mt-4">
    <div class="col-12">
        <div class="alert alert-info">
            <strong>Polling active:</strong> Alert count refreshes every 10 seconds while this page is open.
            Switch warehouses using the dropdown in the top bar — all components update automatically.
        </div>
    </div>
</div>

@code {
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        _alertHandler = () => InvokeAsync(StateHasChanged);

        WarehouseState.OnChange += _warehouseHandler;
        AlertState.OnChange += _alertHandler;

        // Start polling when dashboard becomes visible
        AlertState.StartPolling();
    }

    private async Task RefreshNow()
    {
        await AlertState.RefreshAsync();
    }

    public void Dispose()
    {
        // Stop polling when user leaves the page
        AlertState.StopPolling();

        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;
        if (_alertHandler is not null)
            AlertState.OnChange -= _alertHandler;
    }
}

